function sqParse(text){
  if(typeof text!=='string'||!text.trim()) return { value:null, error:'DSL 为空' };
  var lines=text.split('\n'), actors=[], seen={}, msgs=[];
  for(var i=0;i<lines.length;i++){
    var line=lines[i].trim();
    if(!line||line.charAt(0)==='#') continue;
    var m=line.match(/^([^-<>]+?)\s*(-->|->)\s*([^:]+?)\s*:\s*(.+)$/);
    if(!m) return { value:null, error:'第 '+(i+1)+' 行语法错误（应为 A->B: 消息）' };
    var from=m[1].trim(), to=m[3].trim();
    if(!seen[from]){ seen[from]=1; actors.push(from); }
    if(!seen[to]){ seen[to]=1; actors.push(to); }
    msgs.push({ from:from, to:to, text:m[4].trim(), dashed:m[2]==='-->', self:from===to });
  }
  if(!msgs.length) return { value:null, error:'没有有效消息行' };
  return { value:{ actors:actors, messages:msgs }, error:null };
}
function sqLayout(model){
  var COLW=150, TOP=52, ROWH=42;
  var lanes={}, i;
  for(i=0;i<model.actors.length;i++) lanes[model.actors[i]]=40+i*COLW+COLW/2;
  var arrows=[];
  for(i=0;i<model.messages.length;i++){
    var mg=model.messages[i], y=TOP+28+i*ROWH;
    arrows.push({ x1:lanes[mg.from], x2:lanes[mg.to], y:y, text:mg.text, dashed:mg.dashed, self:mg.self });
  }
  return { lanes:lanes, arrows:arrows,
    width:40+model.actors.length*COLW+20,
    height:TOP+28+model.messages.length*ROWH+30 };
}
function sqEsc(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function sqSvg(text){
  var p=sqParse(text);
  if(p.error) return { value:null, error:p.error };
  var L=sqLayout(p.value);
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+L.width+'" height="'+L.height+'" viewBox="0 0 '+L.width+' '+L.height+'">';
  s+='<defs><marker id="arr" markerWidth="9" markerHeight="7" refX="8" refY="3.5" orient="auto"><polygon points="0 0, 9 3.5, 0 7" fill="#5E6AD2"/></marker></defs>';
  s+='<rect width="'+L.width+'" height="'+L.height+'" fill="#0A0A0B"/>';
  var a, x;
  for(a in L.lanes){
    x=L.lanes[a];
    s+='<line x1="'+x+'" y1="46" x2="'+x+'" y2="'+(L.height-16)+'" stroke="rgba(255,255,255,0.14)" stroke-width="1"/>';
    s+='<rect x="'+(x-58)+'" y="14" width="116" height="28" rx="7" fill="#141417" stroke="#5E6AD2" stroke-width="1.2"/>';
    s+='<text x="'+x+'" y="32" text-anchor="middle" font-size="12" fill="#FFFFFF" font-family="system-ui,sans-serif">'+sqEsc(a.length>13?a.slice(0,12)+'…':a)+'</text>';
  }
  for(var i=0;i<L.arrows.length;i++){
    var ar=L.arrows[i], dash=ar.dashed?' stroke-dasharray="5,4"':'';
    if(ar.self){
      s+='<path d="M'+ar.x1+' '+(ar.y-8)+' h46 v16 h-46" fill="none" stroke="#22D3EE" stroke-width="1.4" marker-end="url(#arr)"'+dash+'/>';
      s+='<text x="'+(ar.x1+52)+'" y="'+ar.y+'" font-size="11" fill="#A1A1AA" font-family="system-ui,sans-serif">'+sqEsc(ar.text)+'</text>';
    } else {
      s+='<line x1="'+ar.x1+'" y1="'+ar.y+'" x2="'+ar.x2+'" y2="'+ar.y+'" stroke="'+(ar.dashed?'#10B981':'#5E6AD2')+'" stroke-width="1.4" marker-end="url(#arr)"'+dash+'/>';
      s+='<text x="'+((ar.x1+ar.x2)/2)+'" y="'+(ar.y-6)+'" text-anchor="middle" font-size="11" fill="#A1A1AA" font-family="system-ui,sans-serif">'+sqEsc(ar.text)+'</text>';
    }
  }
  s+='</svg>';
  return { value:s, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { sqParse:sqParse, sqLayout:sqLayout, sqSvg:sqSvg, sqEsc:sqEsc };
}
if (typeof window !== 'undefined') {
  window.SequenceForgePure = { sqParse:sqParse, sqLayout:sqLayout, sqSvg:sqSvg, sqEsc:sqEsc };
}
